def update_in(coll, path, update, default=None):
    """Creates a copy of coll with a value updated at path."""
    if not path:
        return coll  # Empty top-level path: return unchanged safely
    elif isinstance(coll, list):
        copy = coll[:]
        # NOTE: there is no auto-vivication for lists
        copy[path[0]] = _update_in_recursive(copy[path[0]], path[1:], update, default)
        return copy
    else:
        copy = coll.copy()
        current_default = {} if len(path) > 1 else default
        copy[path[0]] = _update_in_recursive(copy.get(path[0], current_default), path[1:], update, default)
        return copy


def _update_in_recursive(container, path, update, default):
    """Recursive helper for update_in that applies update when path is empty."""
    if not path:
        return update(container)
    elif isinstance(container, list):
        copy = container[:]
        copy[path[0]] = _update_in_recursive(copy[path[0]], path[1:], update, default)
        return copy
    else:
        copy = container.copy()
        current_default = {} if len(path) > 1 else default
        copy[path[0]] = _update_in_recursive(copy.get(path[0], current_default), path[1:], update, default)
        return copy

