def _set_or_update(container, key, path, update, default):
    """Helper for list-based containers."""
    if not path:
        container[key] = update(container.get(key))
    elif isinstance(container.get(key), list):
        if key not in container:
            container[key] = []
        sub = container[key][:]
        sub[path[0]] = _recurse(sub, path[1:], update, default)
        container[key] = sub
    else:
        if key not in container:
            container[key] = {}
        _dict_set_or_update(container[key], path[0], path[1:], update, default)


def _dict_set_or_update(container, key, path, update, default):
    """Helper for dict-based containers."""
    if not path:
        val = container.get(key, {} if default is None else default)
        container[key] = update(val)
    elif isinstance(container.get(key), list):
        if key not in container:
            container[key] = []
        sub = container[key][:]
        if path[0] < len(sub):
            sub[path[0]] = _recurse(sub[path[0]], path[1:], update, default)
        else:
            # Auto-vivication edge case for lists via dicts
            sub.append(_recurse({}, path[1:], update, default))
        container[key] = sub
    else:
        current_default = {} if len(path) > 1 else default
        val = container.get(key, current_default)
        if key not in container:
            container[key] = val if isinstance(val, (dict, list)) else current_default
        if isinstance(val, list):
            sub = val[:]
            sub[path[0]] = _recurse(sub[path[0]], path[1:], update, default)
            container[key] = sub
        else:
            _dict_set_or_update(container[key], path[0], path[1:], update, default)


def _recurse(container, path, update, default):
    """Recursive helper that returns a new container."""
    if not path:
        return update(container)
    elif isinstance(container, list):
        copy = container[:]
        copy[path[0]] = _recurse(copy[path[0]], path[1:], update, default)
        return copy
    else:
        copy = container.copy()
        current_default = {} if len(path) > 1 else default
        copy[path[0]] = _recurse(copy.get(path[0], current_default), path[1:], update, default)
        return copy
